use crate::wasi::clocks::wall_clock;

struct Node;

/// Seconds since the Unix epoch of 9999-12-31T23:59:59Z: the last instant
/// whose calendar date still formats as a 10-character `YYYY-MM-DD`.
const MAX_FORMATTABLE_SECONDS: u64 = 253_402_300_799;

/// Convert days since 1970-01-01 to a proleptic Gregorian (year, month, day).
/// Howard Hinnant's `civil_from_days`.
fn civil_from_days(days: i64) -> (i64, u32, u32) {
    let z = days + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z.rem_euclid(146_097); // [0, 146096]
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365; // [0, 399]
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100); // [0, 365]
    let mp = (5 * doy + 2) / 153; // [0, 11]
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32; // [1, 31]
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32; // [1, 12]
    let year = if m <= 2 { y + 1 } else { y };
    (year, m, d)
}

fn format_date(seconds: u64) -> String {
    // Clamp so the year stays within 0000..=9999 and the date is exactly
    // 10 characters, as the contract requires.
    let secs = seconds.min(MAX_FORMATTABLE_SECONDS);
    let days = (secs / 86_400) as i64;
    let (year, month, day) = civil_from_days(days);
    let year = year.clamp(0, 9_999);
    format!("{:04}-{:02}-{:02}", year, month, day)
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        let now = wall_clock::now();
        let date = format_date(now.seconds);
        RunInfo {
            date,
            started: now.seconds,
        }
    }
}

export!(Node);
